159|  if (bb && bb.length === 3) out.push(bb.join(" × ") + " mm");
160|  if (measure.holes != null) out.push(measure.holes + " holes");
161|  Object.keys(measure).forEach((k) => {
162|    if (k === "solids" || k === "bbox_mm" || k === "bbox" || k === "extents_mm" || k === "holes") return;
