249|async function initViewer(url, holder) {
250|  try {
251|    const probe = document.createElement("canvas");
252|    if (!probe.getContext("webgl")) { holder.style.display = "none"; return; }
253|    const THREE = await import("three");
254|    const orbit = await import("three/addons/controls/OrbitControls.js");
255|    const loaderMod = await import("three/addons/loaders/STLLoader.js");
256|    const w = holder.clientWidth || 400;
257|    const h = 300;
258|    const renderer = new THREE.WebGLRenderer({ antialias: true });
259|    renderer.setSize(w, h);
260|    holder.appendChild(renderer.domElement);
261|    const scene = new THREE.Scene();
262|    scene.background = new THREE.Color(0x101315);
263|    const cam = new THREE.PerspectiveCamera(45, w / h, 0.1, 10000);
264|    const ctl = new orbit.OrbitControls(cam, renderer.domElement);
265|    ctl.autoRotate = true;
266|    ctl.autoRotateSpeed = 1.0;
267|    scene.add(new THREE.HemisphereLight(0xffffff, 0x223333, 1.1));
268|    const lamp = new THREE.DirectionalLight(0xffffff, 1.4);
269|    lamp.position.set(80, 120, 60);
270|    scene.add(lamp);
271|    const geo = await new loaderMod.STLLoader().loadAsync(url);
272|    geo.computeVertexNormals();
273|    const mesh = new THREE.Mesh(
274|      geo,
275|      new THREE.MeshStandardMaterial({ color: 0xb9c2c7, metalness: 0.9, roughness: 0.35 })
276|    );
277|    scene.add(mesh);
278|    const edge = new THREE.LineSegments(
279|      new THREE.EdgesGeometry(geo, 30),
280|      new THREE.LineBasicMaterial({ color: 0x1fa39a })
281|    );
282|    mesh.add(edge);
283|    const box3 = new THREE.Box3().setFromObject(mesh);
284|    const mid = box3.getCenter(new THREE.Vector3());
285|    const size = box3.getSize(new THREE.Vector3());
286|    const far = Math.max(size.x, size.y, size.z) * 2.2;
287|    cam.position.set(mid.x + far, mid.y + far * 0.7, mid.z + far);
288|    ctl.target.copy(mid);
289|    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
290|    ctl.autoRotate = !reduced;
291|    const loop = () => {
292|      requestAnimationFrame(loop);
293|      ctl.update();
294|      renderer.render(scene, cam);
295|    };
296|    loop();
297|  } catch (err) {
298|    holder.style.display = "none";
299|  }
