304|async function readStream(resp, onEvent) {
305|  const reader = resp.body.getReader();
306|  const dec = new TextDecoder();
307|  let tail = "";
308|  for (;;) {
309|    const part = await reader.read();
310|    if (part.done) break;
311|    tail += dec.decode(part.value, { stream: true });
312|    const cut = tail.split("\n\n");
313|    tail = cut.pop();
314|    for (const raw of cut) {
315|      const lines = raw.split("\n");
316|      for (const ln of lines) {
317|        const t = ln.trim();
318|        if (t.indexOf("data:") === 0) {
319|          try {
320|            onEvent(JSON.parse(t.slice(5)));
321|          } catch (err) { /* ignore */ }
322|        }
323|      }
324|    }
325|  }
326|}
327|async function playRecording(label) {
328|  const resp = await fetch("recorded_run.json");
329|  const plan = await resp.json();
330|  const tick = startClock(label);
331|  try {
332|    for (const ev of plan) {
333|      await new Promise((r) => setTimeout(r, 800));
334|      if (ev.step === "done") {
335|        showDone(ev, label);
336|      } else if (ev.step === "error") {
337|        showErrorEvent(ev);
338|      } else {
339|        markEvent(ev);
340|      }
341|    }
342|  } finally {
343|    clearInterval(tick);
344|  }
345|  goBox.classList.add("show");
346|  askBox.classList.add("show");
347|}
348|async function liveRun(job) {
349|  let resp;
350|  try {
351|    resp = await fetch("/api/build", {
352|      method: "POST",
353|      headers: { "Content-Type": "application/json" },
354|      body: JSON.stringify({ job: job })
355|    });
356|  } catch (err) {
357|    say("Could not reach the build service. Please try again.");
358|    return;
359|  }
360|  if (!resp.ok) {
361|    let msg = "The build service answered " + resp.status + ". Please try again.";
362|    try {
363|      const info = await resp.json();
364|      if (info.message) msg = info.message;
365|    } catch (err) { /* ignore */ }
366|    say(cap(msg, 400));
367|    return;
368|  }
369|  const tick = startClock("live run");
370|  try {
371|    await readStream(resp, (ev) => {
372|      if (ev.step === "done") showDone(ev, "live run");
373|      else if (ev.step === "error") showErrorEvent(ev);
374|      else markEvent(ev);
375|    });
376|  } catch (err) {
377|    say("The live run dropped. Please try again.");
378|  } finally {
379|    clearInterval(tick);
380|    askBox.classList.add("show");
381|  }
382|}
383|runBtn.onclick = async () => {
384|  quiet();
385|  resetRun();
386|  runBtn.disabled = true;
387|  try {
388|    let info;
389|    try {
390|      const r = await fetch("/api/status");
391|      info = await r.json();
392|    } catch (err) {
393|      say("Could not reach the demo service. Please try again.");
394|      return;
395|    }
396|    const job = jobBox.value.slice(0, MAX_JOB);
397|    if (info.state === "paused") {
398|      say(info.message || "Demo paused: today's budget is used up. Here is a recorded run instead.");
399|      await playRecording("Recorded run");
400|    } else if (info.state === "waking") {
401|      say("Waking up the model (this takes a few minutes). Here is a recorded run meanwhile.");
402|      await playRecording("Recorded run");
403|      resetRun();
404|      await liveRun(job);
405|    } else {
406|      await liveRun(job);
407|    }
408|  } finally {
409|    runBtn.disabled = false;
410|  }
411|};
